package org.marketreview.nativeapp;
import org.json.*;import static org.marketreview.nativeapp.WatchlistWorkspaceModel.*;
final class IndustryTopicView {
 static String read(JSONObject state,String key)throws Exception{
  if(state.length()==0)return "尚未选择完整产业基线。";if(key.equals("original"))return "最初完整基线原件；旧任务保持停用\n\n"+state.getString("originalArchive");IndustryReportArchive.Parsed parsed=IndustryReportArchive.validate(state.getString("archive"));JSONObject archive=parsed.data;if(key.equals("archive"))return "本机产业完整档案；本机取源不表示远端刷新或事实已核验\n\n"+state.getString("archive");
  if(key.startsWith("job:")){JSONArray jobs=state.getJSONArray("jobs");for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);if(key.substring(4).equals(j.getString("slot")))return "原生产业执行记录\n\n"+j.toString(2);}}
  for(String kind:new String[]{"versions","runs"}){String prefix=kind.equals("versions")?"version:":"run:";if(!key.startsWith(prefix))continue;JSONArray values=archive.getJSONArray(kind);for(int i=0;i<values.length();i++){JSONObject r=values.getJSONObject(i);if(!key.substring(prefix.length()).equals(r.getString("id")))continue;StringBuilder text=new StringBuilder(kind.equals("versions")?"产业版本及完整引用正文\n候选/争议/人工状态沿原记录，不因本机更新升级。\n\n":"产业完整运行原件\n\n");text.append(r.toString(2));if(kind.equals("versions")){JSONArray ids=r.getJSONObject("payload").getJSONArray("evidenceIds"),evidence=archive.getJSONArray("evidence");for(int n=0;n<ids.length();n++)for(int e=0;e<evidence.length();e++){JSONObject source=evidence.getJSONObject(e);if(!ids.getString(n).equals(source.getString("id")))continue;JSONObject p=source.getJSONObject("payload");text.append("\n\n原引用证据 ").append(source.getString("id")).append("\n来源 ").append(source.getString("canonicalUrl")).append("\n发布时刻 ").append(p.isNull("publishedAt")?"未提供":p.optString("publishedAt","未提供")).append("\n获取/本机读取原记录\n").append(p.toString(2)).append("\n\n完整正文\n").append(p.optString("text","原档未提供正文；不补造"));}}return text.toString();}}
  throw new Exception("所选历史原件已缺失，未显示替代版本");
 }
 static JSONArray history(JSONObject state,String topicId)throws Exception{JSONArray out=new JSONArray();if(state.length()==0)return out;JSONObject archive=new JSONObject(state.getString("archive"));for(String k:new String[]{"versions","runs"}){JSONArray a=archive.getJSONArray(k);for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(!topicId.isEmpty()&&!topicId.equals(r.optString("topicId")))continue;out.put(object("key",(k.equals("versions")?"version:":"run:")+r.getString("id"),"label",(k.equals("versions")?"版本 #"+r.getInt("sequence"):"运行 "+r.getString("status"))+" · "+r.getString("id")));}}JSONArray jobs=state.getJSONArray("jobs");for(int i=0;i<jobs.length();i++){JSONObject j=jobs.getJSONObject(i);if(topicId.isEmpty()||topicId.equals(j.getString("topicId")))out.put(object("key","job:"+j.getString("slot"),"label","执行 "+j.getString("status")+" · "+j.getString("startedAt")));}return out;}
}
